def _market_number(value, default=0.0):
    try:
        number = float(value)
    except (TypeError, ValueError):
        return default
    return number if math.isfinite(number) else default


def normalize_xbt_market(payload, now=None):
    if not isinstance(payload, dict) or not payload.get("success"):
        raise ValueError("NeoxEX ticker response was unsuccessful")

    ticker = payload.get("ticker")
    if not isinstance(ticker, dict):
        raise ValueError("NeoxEX ticker payload is missing")

    last_price = _market_number(ticker.get("lastPrice"), -1)
    if last_price <= 0:
        raise ValueError("NeoxEX XBT price is invalid")

    current_time = int(time.time() if now is None else now)
    computed_at = int(_market_number(ticker.get("computedAt"), 0))
    updated_at = computed_at // 1000 if computed_at > 10_000_000_000 else computed_at
    if updated_at <= 0:
        updated_at = current_time

    return {
        "available": True,
        "venue": "Neoxa Exchange",
        "pair": "BTCB2_USDC",
        "displayPair": "XBT / USDC",
        "lastPrice": last_price,
        "changePercent24h": _market_number(ticker.get("changePercent")),
        "high24h": _market_number(ticker.get("high24h")),
        "low24h": _market_number(ticker.get("low24h")),
        "volume24h": _market_number(ticker.get("volume24h")),
        "quoteVolume24h": _market_number(ticker.get("quoteVolume24h")),
        "trades24h": max(0, int(_market_number(ticker.get("trades24h")))),
        "bestBid": _market_number(ticker.get("bestBid")),
        "bestAsk": _market_number(ticker.get("bestAsk")),
        "updatedAt": updated_at,
        "stale": current_time - updated_at > XBT_MARKET_STALE_SECONDS,
    }


def load_xbt_market(now=None):
    current_time = int(time.time() if now is None else now)
    with XBT_MARKET_LOCK:
        cached = XBT_MARKET_CACHE.get("data")
        fetched_at = int(XBT_MARKET_CACHE.get("fetchedAt", 0) or 0)
        if cached and current_time - fetched_at < XBT_MARKET_CACHE_SECONDS:
            return dict(cached)

        try:
            request = urllib.request.Request(
                NEOXEX_XBT_TICKER_URL,
                headers={
                    "Accept": "application/json",
                    "User-Agent": "TerminusPool-Market/0.2.56",
                },
            )
            with urllib.request.urlopen(request, timeout=3) as response:
                market = normalize_xbt_market(
                    json.load(response),
                    now=current_time
                )
            XBT_MARKET_CACHE["data"] = dict(market)
            XBT_MARKET_CACHE["fetchedAt"] = current_time
            return market
        except Exception:
            if cached and current_time - fetched_at <= XBT_MARKET_STALE_SECONDS:
                fallback = dict(cached)
                fallback["stale"] = True
                return fallback
            return {
                "available": False,
                "venue": "Neoxa Exchange",
                "pair": "BTCB2_USDC",
                "displayPair": "XBT / USDC",
                "stale": True,
            }


@contextmanager
def _history_connection():
    os.makedirs(STATE_DIR, exist_ok=True)
    connection = sqlite3.connect(HISTORY_DB, timeout=3)
    try:
        connection.execute("PRAGMA journal_mode=WAL")
        connection.execute("PRAGMA synchronous=NORMAL")
        connection.execute(
            """
            CREATE TABLE IF NOT EXISTS pool_history (
                minute INTEGER PRIMARY KEY,
                hashrate REAL NOT NULL,
                miners INTEGER NOT NULL,
                connections INTEGER NOT NULL,
                accepted INTEGER NOT NULL,
                rejected INTEGER NOT NULL,
                height INTEGER NOT NULL
            )
            """
        )
        connection.execute(
            """
            CREATE TABLE IF NOT EXISTS miner_best_share (
                identity_hash TEXT PRIMARY KEY,
                best_share REAL NOT NULL,
                first_seen_at INTEGER NOT NULL,
                updated_at INTEGER NOT NULL
            )
            """
        )
        connection.execute(
            """
            CREATE TABLE IF NOT EXISTS miner_activity (
                minute INTEGER NOT NULL,
                identity_hash TEXT NOT NULL,
                worker_tag TEXT NOT NULL,
                hashrate_hs REAL NOT NULL,
                work REAL NOT NULL,
                best_share REAL NOT NULL,
                target_work REAL NOT NULL DEFAULT 0,
                PRIMARY KEY (minute, identity_hash)
            )
            """
        )
        activity_columns = {
            row[1] for row in connection.execute(
                "PRAGMA table_info(miner_activity)"
            ).fetchall()
        }
        if "target_work" not in activity_columns:
            connection.execute(
                "ALTER TABLE miner_activity "
                "ADD COLUMN target_work REAL NOT NULL DEFAULT 0"
            )
        connection.execute(
            """
            CREATE INDEX IF NOT EXISTS miner_activity_identity_minute
            ON miner_activity (identity_hash, minute)
            """
        )
        connection.execute(
            """
            CREATE TABLE IF NOT EXISTS miner_profile (
                identity_hash TEXT PRIMARY KEY,
                stable_tag TEXT NOT NULL,
                updated_at INTEGER NOT NULL
            )
            """
        )
        connection.execute(
            """
            CREATE TABLE IF NOT EXISTS block_effort_state (
                singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
                observed_blocks INTEGER NOT NULL,
                estimated_work REAL NOT NULL,
                last_sample_at INTEGER NOT NULL,
                last_hashrate_hs REAL NOT NULL,
                tracking_since INTEGER NOT NULL,
                last_reset_at INTEGER NOT NULL
            )
            """
        )
        connection.commit()
        yield connection
        connection.commit()
    finally:
        connection.close()


def _history_effort_since(connection, since, until):
    """Estimate difficulty-work from durable minute hashrate samples."""
    rows = connection.execute(
        """
        SELECT minute, hashrate
        FROM pool_history
        WHERE minute >= ? AND minute <= ?
        ORDER BY minute ASC
        """,
        (int(since), int(until))
    ).fetchall()
    if not rows:
        return 0.0

    estimated_work = 0.0
    previous_at, previous_ths = rows[0]
    for sampled_at, sampled_ths in rows[1:]:
        elapsed = min(
            BLOCK_EFFORT_MAX_SAMPLE_GAP,
            max(0, int(sampled_at) - int(previous_at))
        )
        average_hs = (
            max(0.0, float(previous_ths or 0)) +
            max(0.0, float(sampled_ths or 0))
        ) * 0.5 * 1_000_000_000_000
        estimated_work += average_hs * elapsed / HASHES_PER_DIFFICULTY
        previous_at, previous_ths = sampled_at, sampled_ths

    tail_seconds = min(
        BLOCK_EFFORT_MAX_SAMPLE_GAP,
        max(0, int(until) - int(previous_at))
    )
    estimated_work += (
        max(0.0, float(previous_ths or 0)) *
        1_000_000_000_000 *
        tail_seconds /
        HASHES_PER_DIFFICULTY
    )
    return estimated_work


def _block_celebration(last_block_at, now):
    found_at = max(0, int(_number(last_block_at)))
    celebration_until = (
        found_at + BLOCK_CELEBRATION_SECONDS
        if found_at > 0 else 0
    )
    celebration_active = (
        found_at > 0 and
        found_at <= now < celebration_until
    )
    return celebration_active, celebration_until


def _update_block_effort(connection, sample, now):
    """Track estimated pool work and reset only on a newly found block."""
    blocks_found = max(0, int(_number(sample.get("blocks", 0))))
    last_block_at = max(0, int(_number(sample.get("lastBlockAt", 0))))
    hashrate_hs = max(
        0.0,
        _number(sample.get("hashrate", 0)) * 1_000_000_000_000
    )
    network_difficulty = max(0.0, _number(sample.get("difficulty", 0)))
    state = connection.execute(
        """
        SELECT observed_blocks, estimated_work, last_sample_at,
               last_hashrate_hs, tracking_since, last_reset_at
        FROM block_effort_state
        WHERE singleton = 1
        """
    ).fetchone()

    if state is None:
        seed_since = last_block_at if last_block_at > 0 else now
        estimated_work = _history_effort_since(
            connection,
            seed_since,
            now
        ) if last_block_at > 0 else 0.0
        tracking_since = seed_since
        last_reset_at = seed_since
    else:
        (
            observed_blocks,
            estimated_work,
            last_sample_at,
            last_hashrate_hs,
            tracking_since,
            last_reset_at,
        ) = state
        if blocks_found != observed_blocks:
            tracking_since = last_block_at if last_block_at > 0 else now
            last_reset_at = tracking_since
            estimated_work = _history_effort_since(
                connection,
                tracking_since,
                now
            ) if last_block_at > 0 else 0.0
        else:
            elapsed = min(
                BLOCK_EFFORT_MAX_SAMPLE_GAP,
                max(0, now - int(last_sample_at))
            )
            average_hs = (
                max(0.0, float(last_hashrate_hs or 0)) +
                hashrate_hs
            ) * 0.5
            estimated_work += (
                average_hs * elapsed / HASHES_PER_DIFFICULTY
            )

    connection.execute(
        """
        INSERT INTO block_effort_state (
            singleton, observed_blocks, estimated_work,
            last_sample_at, last_hashrate_hs,
            tracking_since, last_reset_at
        ) VALUES (1, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(singleton) DO UPDATE SET
            observed_blocks=excluded.observed_blocks,
            estimated_work=excluded.estimated_work,
            last_sample_at=excluded.last_sample_at,
            last_hashrate_hs=excluded.last_hashrate_hs,
            tracking_since=excluded.tracking_since,
            last_reset_at=excluded.last_reset_at
        """,
        (
            blocks_found,
            estimated_work,
            now,
            hashrate_hs,
            tracking_since,
            last_reset_at,
        )
    )

    effort_percent = (
        estimated_work / network_difficulty * 100.0
        if network_difficulty > 0 else 0.0
    )
    celebration_active, celebration_until = _block_celebration(
        last_block_at,
        now,
    )
    return {
        "basis": "estimated-work-since-last-block",
        "estimatedWork": estimated_work,
        "expectedWork": network_difficulty,
        "effortPercent": effort_percent,
        "visualPercent": (
            100.0 if celebration_active
            else min(100.0, max(0.0, effort_percent))
        ),
        "trackingSince": int(tracking_since),
        "lastResetAt": int(last_reset_at),
        "observedBlocks": blocks_found,
        "probabilistic": True,
        "celebrationActive": celebration_active,
        "celebrationUntil": int(celebration_until),
        "celebrationSeconds": BLOCK_CELEBRATION_SECONDS,
    }


def record_history(sample, now=None):
    sampled_at = int(time.time() if now is None else now)
    minute = sampled_at // 60 * 60

    with HISTORY_LOCK:
        with _history_connection() as connection:
            connection.execute(
                """
                INSERT INTO pool_history (
                    minute, hashrate, miners, connections,
                    accepted, rejected, height
                ) VALUES (?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(minute) DO UPDATE SET
                    hashrate=excluded.hashrate,
                    miners=excluded.miners,
                    connections=excluded.connections,
                    accepted=excluded.accepted,
                    rejected=excluded.rejected,
                    height=excluded.height
                """,
                (
                    minute,
                    float(sample.get("hashrate", 0) or 0),
                    int(sample.get("poolMiners", 0) or 0),
                    int(sample.get("connections", 0) or 0),
                    int(sample.get("accepted", 0) or 0),
                    int(sample.get("rejected", 0) or 0),
                    int(sample.get("height", 0) or 0),
                )
            )
            connection.execute(
                "DELETE FROM pool_history WHERE minute < ?",
                (minute - HISTORY_RETENTION_SECONDS,)
            )
            return _update_block_effort(connection, sample, sampled_at)


def load_history(hours=24, max_points=288):
    cutoff = int(time.time()) - (hours * 60 * 60)

    with HISTORY_LOCK:
        with _history_connection() as connection:
            rows = connection.execute(
                """
                SELECT minute, hashrate, miners, connections,
                       accepted, rejected, height
                FROM pool_history
                WHERE minute >= ?
                ORDER BY minute ASC
                """,
                (cutoff,)
            ).fetchall()

    if len(rows) > max_points:
        stride = max(1, len(rows) // max_points)
        sampled = rows[::stride]
        if sampled[-1] != rows[-1]:
            sampled.append(rows[-1])
        rows = sampled[-max_points:]

    points = [
        {
            "ts": row[0],
            "hashrate": row[1],
            "miners": row[2],
            "connections": row[3],
            "accepted": row[4],
            "rejected": row[5],
            "height": row[6],
        }
        for row in rows
    ]

    values = [point["hashrate"] for point in points]
    summary = {
        "samples": len(points),
        "averageHashrate": (
            sum(values) / len(values) if values else 0
        ),
        "peakHashrate": max(values) if values else 0,
        "lowHashrate": min(values) if values else 0,
    }

    return points, summary


def load_history_summary(hours=24):
    cutoff = int(time.time()) - (hours * 60 * 60)
    with HISTORY_LOCK:
        with _history_connection() as connection:
            row = connection.execute(
                """
                SELECT COUNT(*), AVG(hashrate), MAX(hashrate), MIN(hashrate)
                FROM pool_history
                WHERE minute >= ?
                """,
                (cutoff,)
            ).fetchone()
    return {
        "samples": int(row[0] or 0),
        "averageHashrate": float(row[1] or 0),
        "peakHashrate": float(row[2] or 0),
        "lowHashrate": float(row[3] or 0),
    }


def collect_history_forever():
    # The dashboard API remains the single telemetry reader. This
    # background loop performs one local, read-only GET per minute so
    # durable history continues even when no browser is open.
    time.sleep(5)

    while True:
        try:
            with urllib.request.urlopen(
                "http://127.0.0.1:8080" +
                COLLECTOR_PATH +
                "?collector=1",
                timeout=8
            ) as response:
                response.read()
        except Exception:
            pass

        time.sleep(60)


def _number(value, default=0.0):
    try:
        return float(value or 0)
    except (TypeError, ValueError):
        return default


DIFFICULTY_ONE_TARGET = int(
    "00000000ffff0000000000000000000000000000000000000000000000000000",
    16,
)


def _share_difficulty_from_block_hash(block_hash):
    """Return the accepted share difficulty implied by a display-order hash."""
    value = str(block_hash or "").strip().lower()
    if len(value) != 64:
        return 0.0
    try:
        hash_value = int(value, 16)
    except ValueError:
        return 0.0
    if hash_value <= 0:
        return 0.0
    return DIFFICULTY_ONE_TARGET / hash_value


def _mask_identity(identity):
    identity = str(identity or "").strip()
    if len(identity) <= 18:
        return identity or "UNKNOWN"
    return identity[:10] + "…" + identity[-7:]


def _identity_fingerprint(identity):
    normalized = str(identity or "").strip().lower()
    if not normalized:
        return ""
    return hashlib.sha256(normalized.encode("utf-8")).hexdigest()


def _clean_worker_tag(value):
    tag = " ".join(str(value or "").strip().split())[:64]
    return tag or "UNTAGGED"


def record_miner_activity(raw_miners, target_work=0):
    """Record privacy-safe activity and dampen upstream tag flapping."""
    minute = int(time.time()) // 60 * 60
    cutoff = minute - MINER_ACTIVITY_RETENTION_SECONDS
    consensus_cutoff = minute - LEADERBOARD_WINDOW_SECONDS
    observed_hashes = []

    with HISTORY_LOCK:
        with _history_connection() as connection:
            for raw in raw_miners:
                identity_hash = _identity_fingerprint(raw.get("identity", ""))
                if not identity_hash:
                    continue
                observed_hashes.append(identity_hash)
                connection.execute(
                    """
                    INSERT INTO miner_activity (
                        minute, identity_hash, worker_tag,
                        hashrate_hs, work, best_share, target_work
                    ) VALUES (?, ?, ?, ?, ?, ?, ?)
                    ON CONFLICT(minute, identity_hash) DO UPDATE SET
                        worker_tag=excluded.worker_tag,
                        hashrate_hs=excluded.hashrate_hs,
                        work=excluded.work,
                        best_share=excluded.best_share,
                        target_work=excluded.target_work
                    """,
                    (
                        minute,
                        identity_hash,
                        _clean_worker_tag(raw.get("tag", "")),
                        max(0.0, _number(raw.get("hashrate_hs", 0))),
                        max(0.0, _number(raw.get("work", 0))),
                        max(0.0, _number(raw.get("best_share", 0))),
                        max(0.0, _number(target_work, 0)),
                    )
                )

            connection.execute(
                "DELETE FROM miner_activity WHERE minute < ?",
                (cutoff,)
            )

            for identity_hash in set(observed_hashes):
                counts = connection.execute(
                    """
                    SELECT worker_tag, COUNT(*) AS samples, MAX(minute) AS latest
                    FROM miner_activity
                    WHERE identity_hash = ?
                      AND minute >= ?
                      AND hashrate_hs > 0
                    GROUP BY worker_tag
                    ORDER BY samples DESC, latest DESC, worker_tag ASC
                    """,
                    (identity_hash, consensus_cutoff)
                ).fetchall()
                if not counts:
                    continue

                winner, winner_count, _ = counts[0]
                profile = connection.execute(
                    "SELECT stable_tag FROM miner_profile WHERE identity_hash = ?",
                    (identity_hash,)
                ).fetchone()

                if not profile:
                    connection.execute(
                        """
                        INSERT INTO miner_profile (
                            identity_hash, stable_tag, updated_at
                        ) VALUES (?, ?, ?)
                        """,
                        (identity_hash, winner, minute)
                    )
                    continue

                stable_tag = profile[0]
                if winner == stable_tag:
                    continue

                stable_count = next(
                    (row[1] for row in counts if row[0] == stable_tag),
                    0
                )
                if (
                    winner_count >= TAG_SWITCH_MIN_SAMPLES and
                    winner_count >= max(1, stable_count) * TAG_SWITCH_RATIO
                ):
                    connection.execute(
                        """
                        UPDATE miner_profile
                        SET stable_tag = ?, updated_at = ?
                        WHERE identity_hash = ?
                        """,
                        (winner, minute, identity_hash)
                    )


def load_stable_tags(raw_miners):
    pairs = [
        (str(raw.get("identity", "") or "").strip(),
         _identity_fingerprint(raw.get("identity", "")))
        for raw in raw_miners
    ]
    pairs = [(identity, fingerprint) for identity, fingerprint in pairs
             if identity and fingerprint]
    if not pairs:
        return {}

    keys = [fingerprint for _, fingerprint in pairs]
    placeholders = ",".join("?" for _ in keys)
    with HISTORY_LOCK:
        with _history_connection() as connection:
            rows = connection.execute(
                "SELECT identity_hash, stable_tag FROM miner_profile "
                f"WHERE identity_hash IN ({placeholders})",
                keys
            ).fetchall()
    by_hash = {row[0]: row[1] for row in rows}
    return {
        identity: by_hash.get(fingerprint, "")
        for identity, fingerprint in pairs
    }


def load_public_leaderboard(limit=100):
    """Return only pseudonymous accounts active during the rolling 24h."""
    now = int(time.time())
    cutoff = now - LEADERBOARD_WINDOW_SECONDS
    with HISTORY_LOCK:
        with _history_connection() as connection:
            sample_minutes = connection.execute(
                """
                SELECT COUNT(DISTINCT minute)
                FROM miner_activity
                WHERE minute >= ?
                """,
                (cutoff,)
            ).fetchone()[0] or 0
            rows = connection.execute(
                """
                SELECT
                    activity.identity_hash,
                    COALESCE(profile.stable_tag, 'UNTAGGED'),
                    SUM(activity.hashrate_hs),
                    MAX(activity.hashrate_hs),
                    SUM(CASE WHEN activity.hashrate_hs > 0 THEN 1 ELSE 0 END),
                    MAX(CASE WHEN activity.hashrate_hs > 0 THEN activity.minute END),
                    MAX(activity.best_share),
                    (
                        SELECT latest.work
                        FROM miner_activity AS latest
                        WHERE latest.identity_hash = activity.identity_hash
                          AND latest.minute >= ?
                        ORDER BY latest.minute DESC
                        LIMIT 1
                    ),
                    (
                        SELECT latest.target_work
                        FROM miner_activity AS latest
                        WHERE latest.identity_hash = activity.identity_hash
                          AND latest.minute >= ?
                        ORDER BY latest.minute DESC
                        LIMIT 1
                    ),
                    MAX(activity.minute)
                FROM miner_activity AS activity
                LEFT JOIN miner_profile AS profile
                  ON profile.identity_hash = activity.identity_hash
                WHERE activity.minute >= ?
                GROUP BY activity.identity_hash, profile.stable_tag
                HAVING MAX(CASE WHEN activity.hashrate_hs > 0
                                THEN activity.minute END) IS NOT NULL
                ORDER BY SUM(activity.hashrate_hs) DESC,
                         MAX(activity.hashrate_hs) DESC
                LIMIT ?
                """,
                (cutoff, cutoff, cutoff, int(limit))
            ).fetchall()

    miners = []
    for rank, row in enumerate(rows, 1):
        (
            identity_hash, tag, total_hs, peak_hs, active_minutes,
            last_active, best, latest_work, latest_target, last_observed
        ) = row
        inactive_for = max(0, now - int(last_active))
        if inactive_for <= LEADERBOARD_LIVE_GRACE_SECONDS:
            status = "live"
        elif inactive_for <= LEADERBOARD_RECENT_GRACE_SECONDS:
            status = "recent"
        else:
            status = "seen"
        miners.append({
            "rank": rank,
            "alias": "MINER-" + identity_hash[:8].upper(),
            "tag": _clean_worker_tag(tag),
            "status": status,
            "averageHashrateThs": (
                _number(total_hs) / max(1, int(sample_minutes)) /
                1_000_000_000_000
            ),
            "peakHashrateThs": _number(peak_hs) / 1_000_000_000_000,
            "activeMinutes": int(active_minutes or 0),
            "lastActiveAt": int(last_active),
            "bestShare": _number(best),
            "latestWork": max(0, int(_number(latest_work, 0))),
            "latestTargetWork": max(0, int(_number(latest_target, 0))),
            "lastObservedAt": int(last_observed),
        })

    current_cutoff = now - 180
    current_max_work = max(
        (
            miner["latestWork"] for miner in miners
            if miner["lastObservedAt"] >= current_cutoff
        ),
        default=0
    )
    for miner in miners:
        is_current = miner["lastObservedAt"] >= current_cutoff
        latest_work = miner.pop("latestWork")
        latest_target = miner.pop("latestTargetWork")
        miner["reward"] = work_reward(
            latest_work,
            latest_target,
            is_leader=(
                is_current and current_max_work > 0 and
                latest_work == current_max_work
            )
        ) if is_current else {
            "cosmic": None,
            "specials": [],
            "targetPercent": 0,
        }
        miner.pop("lastObservedAt", None)

    return {
        "generatedAt": now,
        "windowHours": 24,
        "liveGraceMinutes": LEADERBOARD_LIVE_GRACE_SECONDS // 60,
        "recentGraceMinutes": LEADERBOARD_RECENT_GRACE_SECONDS // 60,
        "ranking": "average-hashrate",
        "privacy": "opaque-aliases-no-payout-addresses",
        "miners": miners,
    }


def sync_all_time_best_shares(raw_miners):
    """Persist and return the highest RATUM best share per identity."""
    now = int(time.time())
    observations = []

    for raw in raw_miners:
        identity = str(raw.get("identity", "") or "").strip()
        identity_hash = _identity_fingerprint(identity)
        if not identity_hash:
            continue
        observations.append((
            identity,
            identity_hash,
            max(0.0, _number(raw.get("best_share", 0))),
        ))

    if not observations:
        return {}, 0

    with HISTORY_LOCK:
        with _history_connection() as connection:
            for _, identity_hash, best_share in observations:
                connection.execute(
                    """
                    INSERT INTO miner_best_share (
                        identity_hash, best_share,
                        first_seen_at, updated_at
                    ) VALUES (?, ?, ?, ?)
                    ON CONFLICT(identity_hash) DO UPDATE SET
                        best_share = CASE
                            WHEN excluded.best_share > miner_best_share.best_share
                            THEN excluded.best_share
                            ELSE miner_best_share.best_share
                        END,
                        updated_at = CASE
                            WHEN excluded.best_share > miner_best_share.best_share
                            THEN excluded.updated_at
                            ELSE miner_best_share.updated_at
                        END
                    """,
                    (identity_hash, best_share, now, now)
                )

            keys = [item[1] for item in observations]
            placeholders = ",".join("?" for _ in keys)
            rows = connection.execute(
                "SELECT identity_hash, best_share FROM miner_best_share "
                f"WHERE identity_hash IN ({placeholders})",
                keys
            ).fetchall()
            tracking_since = connection.execute(
                "SELECT MIN(first_seen_at) FROM miner_best_share"
            ).fetchone()[0] or 0

    by_hash = {row[0]: float(row[1]) for row in rows}
    return {
        identity: by_hash.get(identity_hash, best_share)
        for identity, identity_hash, best_share in observations
    }, int(tracking_since)


def work_reward(work, target_work, is_leader=False):
    work_value = max(0, int(_number(work, 0)))
    target_value = max(0, int(_number(target_work, 0)))
    ratio = work_value / target_value if target_value else 0.0
    cosmic = None

    for threshold, emoji, label in WORK_REWARD_TIERS:
        if ratio >= threshold:
            cosmic = {
                "emoji": emoji,
                "label": label,
                "thresholdPercent": threshold * 100,
            }
            break

    specials = []
    if target_value and ratio >= DIAMOND_WORK_RATIO:
        specials.append({
            "emoji": "💎",
            "label": "DIAMOND WORK",
        })
    if is_leader and work_value > 0:
        specials.append({
            "emoji": "👑",
            "label": "CURRENT WINDOW LEADER",
        })

    return {
        "cosmic": cosmic,
        "specials": specials,
        "targetPercent": ratio * 100,
    }


def window_work_progress(work, target_work):
    """Return bounded aggregate payout-window completion percentage."""
    work_value = max(0.0, _number(work, 0))
    target_value = max(0.0, _number(target_work, 0))
    if target_value <= 0:
        return 0.0
    return min(100.0, (work_value / target_value) * 100.0)


def load_admin_snapshot(reveal=False):
    """Return read-only per-account telemetry from RATUM Prime."""
    with urllib.request.urlopen(PRIME, timeout=2.5) as response:
        prime = json.load(response)

    window = prime.get("window", {})
    raw_miners = window.get("miners", [])
    stable_tags = load_stable_tags(raw_miners)
    all_time_best, all_time_tracking_since = (
        sync_all_time_best_shares(raw_miners)
    )
    target_work = int(_number(window.get("target_work", 0)))
    max_work = max(
        (int(_number(raw.get("work", 0))) for raw in raw_miners),
        default=0
    )
    miners = []

    for raw in raw_miners:
        identity = str(raw.get("identity", "") or "").strip()
        hashrate_hs = _number(raw.get("hashrate_hs", 0))
        payout_sats = int(_number(raw.get("payout_sats", 0)))
        miner_work = int(_number(raw.get("work", 0)))
        window_best_share = _number(raw.get("best_share", 0))
        miners.append({
            "identity": identity if reveal else _mask_identity(identity),
            "identityMasked": not reveal,
            "tag": stable_tags.get(identity) or _clean_worker_tag(
                raw.get("tag", "")
            ),
            "status": "active" if hashrate_hs > 0 else "idle",
            "hashrateThs": hashrate_hs / 1_000_000_000_000,
            "sharePercent": _number(raw.get("share_percent", 0)),
            "work": str(miner_work),
            "reward": work_reward(
                miner_work,
                target_work,
                is_leader=(miner_work == max_work and max_work > 0)
            ),
            "bestShare": window_best_share,
            "windowBestShare": window_best_share,
            "allTimeBestShare": max(
                window_best_share,
                _number(all_time_best.get(identity, 0))
            ),
            "projectedPayoutSats": payout_sats,
            "projectedPayoutXbt": payout_sats / 100_000_000,
            "payable": bool(raw.get("payable", False)),
            "unpayableReason": str(
                raw.get("unpayable_reason", "") or ""
            ),
        })

    miners.sort(
        key=lambda item: (item["status"] != "active", -item["hashrateThs"])
    )

    active = sum(1 for miner in miners if miner["status"] == "active")
    return {
        "generatedAt": int(time.time()),
        "scope": "ratum-payout-window",
        "privacy": "revealed" if reveal else "masked",
        "allTimeTrackingSince": all_time_tracking_since,
        "rewardScale": {
            "basis": "percent-of-target-window-work",
            "targetWork": str(target_work),
            "tiers": [
                {
                    "thresholdPercent": threshold * 100,
                    "emoji": emoji,
                    "label": label,
                }
                for threshold, emoji, label in reversed(WORK_REWARD_TIERS)
            ],
            "diamondThresholdPercent": DIAMOND_WORK_RATIO * 100,
        },
        "summary": {
            "accounts": len(miners),
            "active": active,
            "idle": len(miners) - active,
            "hashrateThs": sum(m["hashrateThs"] for m in miners),
            "projectedPayoutXbt": sum(
                m["projectedPayoutXbt"] for m in miners
            ),
        },
        "miners": miners,
    }

